fn solve(w: i8, a: i8, b: i8) -> i8 {
    // Compute the absolute distance between the two starting points
    let dist = (a - b).abs();
    // If they already touch or overlap, no shift is needed
    if dist <= w {
        0
    } else {
        // Otherwise, subtract the width to get the minimal shift
        dist - w
    }
}

